 n=struct.unpack('>I',p[pos:pos+4])[0]; typ=p[pos+4:pos+8]; dat=p[pos+8:pos+8+n]; pos+=12+n
 if typ==b'IHDR': W,H,bd,ct,comp,filt,inter=struct.unpack('>IIBBBBB',dat)
 if typ==b'IDAT': idat+=dat
raw=zlib.decompress(idat); ch={0:1,2:3,4:2,6:4}[ct]; stride=W*ch; out=[]; prev=bytearray(stride); pp=0
