   q=a+b-c; pa=abs(q-a); pb=abs(q-b); pc=abs(q-c); pr=a if pa<=pb and pa<=pc else (b if pb<=pc else c); row[x]=(row[x]+pr)&255
  elif f: raise Exception(f)
 out.append([row[x*ch] for x in range(W)]); prev=row
